const ACCESS_EMAIL="devon@anevum.com";
const HOST="sites.anevum.com";
const ACCESS_ISSUER="https://wispy-tooth-095a.cloudflareaccess.com";
const ACCESS_AUD="49d01711c88699db02ba1bc203588dc4b43d4d262b84b964dcf2230b60f7161c";
let JWKS_CACHE=null,JWKS_UPDATED=0;
function unb64(s){const t=s.replace(/-/g,"+").replace(/_/g,"/");return Uint8Array.from(atob(t+"=".repeat((4-t.length%4)%4)),c=>c.charCodeAt(0))}
async function verifiedOwner(req){
 const token=req.headers.get("Cf-Access-Jwt-Assertion");if(!token)return false;
 const parts=token.split(".");if(parts.length!==3)return false;
 try {
  const header=JSON.parse(new TextDecoder().decode(unb64(parts[0])));
  const body=JSON.parse(new TextDecoder().decode(unb64(parts[1])));
  const clock=Math.floor(Date.now()/1000);
  if(header.alg!=="RS256"||!header.kid||body.iss!==ACCESS_ISSUER)return false;
  if(!body.exp||body.exp<=clock||(body.nbf&&body.nbf>clock))return false;
  const aud=Array.isArray(body.aud)?body.aud:[body.aud];
  if(!aud.includes(ACCESS_AUD)||String(body.email||"").toLowerCase()!==ACCESS_EMAIL)return false;
  if(!JWKS_CACHE||Date.now()-JWKS_UPDATED>3600000){
   const r=await fetch(ACCESS_ISSUER+"/cdn-cgi/access/certs");if(!r.ok)return false;
   const j=await r.json();JWKS_CACHE=j.keys||[];JWKS_UPDATED=Date.now();
  }
  let jwk=JWKS_CACHE.find(x=>x.kid===header.kid);
  if(!jwk){JWKS_UPDATED=0;const r=await fetch(ACCESS_ISSUER+"/cdn-cgi/access/certs");if(!r.ok)return false;const j=await r.json();JWKS_CACHE=j.keys||[];JWKS_UPDATED=Date.now();jwk=JWKS_CACHE.find(x=>x.kid===header.kid)}
  if(!jwk)return false;
  const key=await crypto.subtle.importKey("jwk",jwk,{name:"RSASSA-PKCS1-v1_5",hash:"SHA-256"},false,["verify"]);
  return await crypto.subtle.verify("RSASSA-PKCS1-v1_5",key,unb64(parts[2]),new TextEncoder().encode(parts[0]+"."+parts[1]));
 }catch{return false}
}

